#!/usr/bin/env python3
"""MiniMCProto V2 跨仓（soc-ap / mcu-p3 MC / mcu-p3 TH）全量命令字静态对齐门禁。"""

import pathlib
import re
import sys
from typing import Dict, List, Set, Tuple

# 权威 MiniMCProto V2 命令字矩阵：(标准语义名, 期望数值, 允许别名元组)
EXPECTED_OPCODES: List[Tuple[str, int, Tuple[str, ...]]] = [
    ("ACK", 0x00, ("MINIMC_CMD_ACK",)),
    ("GET_VERSION", 0x01, ("MINIMC_CMD_GET_VERSION",)),
    ("VERSION_REPORT", 0x02, ("MINIMC_CMD_VERSION_REPORT",)),
    ("PING", 0x03, ("MINIMC_CMD_PING",)),
    ("PONG", 0x04, ("MINIMC_CMD_PONG",)),
    ("NACK", 0x06, ("MINIMC_CMD_NACK",)),
    ("SET_TEMP", 0x10, ("MINIMC_CMD_SET_TEMP",)),
    ("MOTION_HOME", 0x11, ("MINIMC_CMD_MOTION_HOME",)),
    ("MOTION_MOVE", 0x12, ("MINIMC_CMD_MOTION_MOVE",)),
    ("JOB_CONTROL", 0x13, ("MINIMC_CMD_JOB_CONTROL",)),
    ("TEMP_REPORT", 0x15, ("MINIMC_CMD_TEMP_REPORT", "MINIMC_CMD_TEMP_REPORT_V2")),
    ("POS_QUERY", 0x16, ("MINIMC_CMD_POS_QUERY",)),
    ("MOTION_STOP", 0x17, ("MINIMC_CMD_MOTION_STOP",)),
    ("LEVEL_GRID_QUERY", 0x18, ("MINIMC_CMD_LEVEL_GRID_QUERY",)),
    ("SLOT_SELECT", 0x19, ("MINIMC_CMD_SLOT_SELECT",)),
    ("LEVEL_TRIGGER", 0x1A, ("MINIMC_CMD_LEVEL_TRIGGER",)),
    ("GCODE_EXEC", 0x1C, ("MINIMC_CMD_GCODE_EXEC",)),
]

MACRO_RE = re.compile(
    r"(?:#define\s+|constexpr\s+uint8_t\s+)(MINIMC_CMD_[A-Z0-9_]+)\s*=?\s*(0x[0-9A-Fa-f]+)"
)


def parse_header_macros(paths: List[pathlib.Path]) -> Dict[str, int]:
    """从一组 C/C++ 头文件中提取 MINIMC_CMD_* 宏或常量定义映射表。"""
    if not paths:
        return {}
    macros: Dict[str, int] = {}
    for path in paths:
        if not path.is_file():
            raise FileNotFoundError(f"Missing required header file: {path}")
        content = path.read_text(encoding="utf-8")
        for match in MACRO_RE.finditer(content):
            macros[match.group(1)] = int(match.group(2), 16)
    return macros


def resolve_endpoint_opcode(
    macros: Dict[str, int],
    aliases: Tuple[str, ...],
) -> Tuple[int, List[str]]:
    """在单侧头文件宏字典中解析指定语义命令字的数值与不一致项。"""
    if not macros or not aliases:
        return -1, ["no macro found"]
    found_vals: Set[int] = set()
    for alias in aliases:
        if alias in macros:
            found_vals.add(macros[alias])
    if not found_vals:
        return -1, [f"missing any of {aliases}"]
    if len(found_vals) > 1:
        hex_list = [f"0x{v:02X}" for v in sorted(found_vals)]
        return -1, [f"conflicting alias values {hex_list} for {aliases}"]
    return next(iter(found_vals)), []


def verify_single_opcode(
    name: str,
    expected_val: int,
    aliases: Tuple[str, ...],
    endpoint_map: Dict[str, Dict[str, int]],
) -> List[str]:
    """校验单个命令字在 AP、MC、TH 三侧头文件中的定义是否与权威值严格一致。"""
    errors: List[str] = []
    for ep_label, macros in endpoint_map.items():
        actual_val, ep_errs = resolve_endpoint_opcode(macros, aliases)
        if ep_errs:
            errors.append(f"[{ep_label}] {name} (0x{expected_val:02X}): {'; '.join(ep_errs)}")
            continue
        if actual_val != expected_val:
            errors.append(
                f"[{ep_label}] {name} mismatch: expected 0x{expected_val:02X}, got 0x{actual_val:02X}"
            )
    return errors


def load_endpoint_headers(workspace_root: pathlib.Path) -> Dict[str, Dict[str, int]]:
    """加载 soc-ap、mcu-p3 (MC) 与 mcu-p3 (TH) 三侧协议头文件的命令字表。"""
    ap_headers = [
        workspace_root / "soc-ap/contracts/twin/telemetry_types.h",
    ]
    mc_headers = [
        workspace_root / "mcu-p3/motion-controller-mcu/project/inc/minimc_proto.h",
    ]
    th_headers = [
        workspace_root / "mcu-p3/color-engine-mcu/io_toggle/inc/minimc_proto.h",
    ]
    return {
        "soc-ap": parse_header_macros(ap_headers),
        "mcu-p3(MC)": parse_header_macros(mc_headers),
        "mcu-p3(TH)": parse_header_macros(th_headers),
    }


def main() -> int:
    """执行跨仓 MiniMCProto V2 命令字对齐检查，任何缺失或不一致返回非 0。"""
    workspace_root = pathlib.Path(__file__).resolve().parents[3]
    print("=== MiniMCProto V2 Cross-Repo Opcode Alignment Gate ===")
    try:
        endpoint_map = load_endpoint_headers(workspace_root)
    except FileNotFoundError as exc:
        print(f"[FATAL] {exc}", file=sys.stderr)
        return 1

    all_errors: List[str] = []
    for name, expected_val, aliases in EXPECTED_OPCODES:
        item_errs = verify_single_opcode(name, expected_val, aliases, endpoint_map)
        if item_errs:
            all_errors.extend(item_errs)
            print(f"  [FAIL] 0x{expected_val:02X} ({name})")
        else:
            print(f"  [OK]   0x{expected_val:02X} ({name:<17}) aligned across soc-ap / MC / TH")

    if all_errors:
        print("\n[FAILED] Opcode alignment check failed:", file=sys.stderr)
        for err in all_errors:
            print(f"  - {err}", file=sys.stderr)
        return 1

    print(f"\n[PASSED] All {len(EXPECTED_OPCODES)} MiniMCProto V2 opcodes are 100% aligned.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
* **处理规约**：接收端从 Flash 物理回读整块镜像，全量比对 CRC32。比对成功写入启动标志并回送 `CMD_ACK`；若指定 `action_after_verify == 1`，延迟 100ms 后触发系统软复位生效。

##### (4) 固件升级进度与状态查询 (`CMD_OTA_STATUS = 0x23`)
AP 可主动下发查询请求（载荷 0B），接收端回显固定 **8 字节** 状态（亦可作为单向通知上报）：
```c
struct __attribute__((packed)) minimc_payload_ota_status {
    uint8_t  ota_state;           // 0=IDLE, 1=ERASING, 2=RECEIVING, 3=VERIFYING, 4=SUCCESS, 5=ERROR
    uint8_t  error_code;          // 故障代码: 0=OK, 其它见标准 NACK 错误码
    uint16_t reserved;            // 对齐填充，置 0
    uint32_t bytes_written;       // 已成功写入 Flash 的物理字节数 (断点续传恢复基准)
};
```

#### 6. 切片流与切片块原子入队载荷 (`CMD_STREAM_CHUNK`)
载荷由 **8 字节固定事务头 + 紧随其后的 G-code 文本数据** 组成：
```c
struct __attribute__((packed)) minimc_payload_stream_chunk {
    uint16_t job_id;              // 打印作业唯一编号 (作业切换时变更)
    uint16_t chunk_seq;           // 块序号 (从 0 开始单调递增)
    uint16_t text_bytes;          // 紧随其后的 G-code 文本字节数 (0 ~ 1016)
    uint8_t  chunk_flags;         // Bit 0: LAST_CHUNK, Bit 1: BARRIER, 其余保留 0
    uint8_t  reserved;            // 对齐填充，置 0
    uint8_t  gcode_text[];        // G-code 纯文本 (以 LF 分隔各完整行)
};
```
